PowerShell# 修改1: D:\Code\CLAUDE.md# 作用: 读取 CLAUDE.md，找到 Win11/i9-14900KF/64GB 环境行，在其后插入 Node 非 LTS 备注$claudePath = "D:\Code\CLAUDE.md"$noteLine = "- Node 24.18.0 非 LTS 稳定基线，如 pipeline 扩展依赖优先建立 Node 22 LTS 备用方案"$lines = Get-Content -LiteralPath $claudePath -Encoding UTF8if ($lines -notcontains $noteLine) { $idx = -1 for ($i = 0; $i -lt $lines.Count; $i++) { if ($lines[$i] -match "Win11.*i9-14900KF.*64GB") { $idx = $i break } } if ($idx -ge 0) { $newLines = @() $newLines += $lines[0..$idx] $newLines += $noteLine if ($idx + 1 -lt $lines.Count) { $newLines += $lines[($idx + 1)..($lines.Count - 1)] } $newLines | Set-Content -LiteralPath $claudePath -Encoding UTF8 } else { throw "未找到当前环境行: Win11/i9-14900KF/64GB" }}
PowerShell# 修改2: D:\Code\health.ps1# 作用: 增加 Playwright Chromium 可执行文件检查# 插入位置: health.ps1 的检查项区域；如果已有 Add-HealthCheck / $checks，请按现有格式挂载此检查函数function Test-PlaywrightChromiumHealth { Set-StrictMode -Version 2.0 $ErrorActionPreference = "Continue" $pipelineDir = Join-Path $env:CLAUDE_PROJECT_DIR "ai-pipeline" if (-not $env:CLAUDE_PROJECT_DIR) { $pipelineDir = Join-Path (Split-Path -Parent $PSScriptRoot) "ai-pipeline" } $result = [ordered]@{ name = "playwright_chromium" ok = $false chromium_path = "" error = "" } try { if (-not (Test-Path -LiteralPath $pipelineDir)) { $result.error = "pipeline dir not found: $pipelineDir" return [pscustomobject]$result } $nodeCode = "const { chromium } = require('playwright'); console.log(chromium.executablePath())" $output = & node -e $nodeCode 2>&1 $exitCode = $LASTEXITCODE if ($exitCode -ne 0) { $result.error = ($output -join "`n") return [pscustomobject]$result } $chromiumPath = (($output | Select-Object -Last 1) -as [string]).Trim() $result.chromium_path = $chromiumPath if ([string]::IsNullOrWhiteSpace($chromiumPath)) { $result.error = "chromium executablePath is empty" return [pscustomobject]$result } if (-not (Test-Path -LiteralPath $chromiumPath)) { $result.error = "chromium executable not found" return [pscustomobject]$result } $result.ok = $true return [pscustomobject]$result } catch { $result.error = $_.Exception.Message return [pscustomobject]$result } finally { Pop-Location -ErrorAction SilentlyContinue }}# 挂载到 health 汇总处：# 注意: 必须 Push-Location 到 D:\Code\ai-pipeline，确保 require('playwright') 使用 ai-pipeline\node_modulesPush-Location -LiteralPath (Join-Path $env:CLAUDE_PROJECT_DIR "ai-pipeline")$playwrightChromiumCheck = Test-PlaywrightChromiumHealthPop-Location# 若 health.ps1 使用 $checks 数组：$checks += $playwrightChromiumCheck# 若 health.ps1 使用失败计数：if (-not $playwrightChromiumCheck.ok) { $script:failCount += 1}
PowerShell# 修改3-A: D:\Code\.claude\agent-router.json# 作用: 根节点新增 disabled_capabilities / disabled_reason$routerPath = "D:\Code\.claude\agent-router.json"$router = Get-Content -LiteralPath $routerPath -Raw -Encoding UTF8 | ConvertFrom-Jsonif ($router.PSObject.Properties.Name -contains "disabled_capabilities") { $router.disabled_capabilities = @("docker", "wsl", "rust", "go")}else { $router | Add-Member -NotePropertyName "disabled_capabilities" -NotePropertyValue @("docker", "wsl", "rust", "go")}if ($router.PSObject.Properties.Name -contains "disabled_reason") { $router.disabled_reason = "环境未安装，CLAUDE.md已声明不可用"}else { $router | Add-Member -NotePropertyName "disabled_reason" -NotePropertyValue "环境未安装，CLAUDE.md已声明不可用"}$router | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $routerPath -Encoding UTF8# 修改3-B: D:\Code\health.ps1# 作用: 读取 disabled_capabilities 并显示数量# 插入位置: health.ps1 的检查项区域function Test-AgentRouterDisabledCapabilitiesHealth { Set-StrictMode -Version 2.0 $ErrorActionPreference = "Continue" $projectDir = $env:CLAUDE_PROJECT_DIR if (-not $projectDir) { $projectDir = Split-Path -Parent $PSScriptRoot } $routerPath = Join-Path $projectDir ".claude\agent-router.json" $result = [ordered]@{ name = "agent_router_disabled_capabilities" ok = $true count = 0 disabled_capabilities = @() error = "" } try { if (-not (Test-Path -LiteralPath $routerPath)) { $result.ok = $false $result.error = "agent-router.json not found: $routerPath" return [pscustomobject]$result } $router = Get-Content -LiteralPath $routerPath -Raw -Encoding UTF8 | ConvertFrom-Json if ($router.PSObject.Properties.Name -contains "disabled_capabilities" -and $null -ne $router.disabled_capabilities) { $disabled = @($router.disabled_capabilities) $result.count = $disabled.Count $result.disabled_capabilities = $disabled } Write-Host ("disabled_capabilities count={0}: {1}" -f $result.count, ($result.disabled_capabilities -join ", ")) return [pscustomobject]$result } catch { $result.ok = $false $result.error = $_.Exception.Message return [pscustomobject]$result }}# 挂载到 health 汇总处：$disabledCapabilitiesCheck = Test-AgentRouterDisabledCapabilitiesHealth# 若 health.ps1 使用 $checks 数组：$checks += $disabledCapabilitiesCheck# 若 health.ps1 使用失败计数：if (-not $disabledCapabilitiesCheck.ok) { $script:failCount += 1}
